import assert from 'node:assert/strict';
const ok=async(response,status=200)=>{assert.equal(response.status,status,await response.clone().text());return response.json();};
export async function exerciseBackupMaintenance({request,admin,prepare,step,restart,inspect}){
 const path='/api/admin/backups',ids=await prepare(),state=await ok(await request(path,{account:admin}));assert.equal(state.cleanup.available,true);assert.equal(state.cleanup.approved,false);const destinationProfileId=state.destination.profileId,body={destinationProfileId};
 assert.equal((await request(path+'/cleanup/preview',{method:'POST',account:admin,headers:{'X-Yumunio-Expected-Account':'different'},body})).status,404);assert.equal((await request(path+'/cleanup/preview',{method:'POST',account:admin,headers:{Origin:'https://foreign.fixture.invalid'},body})).status,404);
 const preview=await ok(await request(path+'/cleanup/preview',{method:'POST',account:admin,body}));assert.equal(preview.keeper.backupId,ids.keeper);assert.deepEqual(preview.candidates.map(item=>item.backupId),[ids.old]);assert.equal((await inspect(ids)).oldPresent,true);const consent={destinationProfileId,policyDigest:preview.policyDigest,planDigest:preview.planDigest,expectedVersion:preview.approvalVersion,confirmScope:'expired-app-backup-artifacts',confirmQuiescent:true};assert.equal((await request(path+'/cleanup/approval',{method:'POST',account:admin,body:{...consent,confirmQuiescent:false}})).status,400);
 const approved=await ok(await request(path+'/cleanup/approval',{method:'POST',account:admin,body:consent}));assert.equal(approved.cleanup.approved,true);await step();await restart();let status;for(let count=0;count<40;count++){status=await ok(await request(path+'/cleanup/jobs',{account:admin}));if(status.cleanup.jobs[0]?.status==='complete')break;await step();}assert.equal(status.cleanup.jobs[0].status,'complete');const result=await inspect(ids);assert.equal(result.oldPresent,false);assert.equal(result.keeperVerified,true);assert.equal(result.foreignPresent,true);assert.equal(result.livePresent,true);assert.equal(result.externalAttempts,0);const stopped=await ok(await request(path+'/cleanup/approval',{method:'DELETE',account:admin,body:{destinationProfileId,expectedVersion:status.cleanup.approvalVersion}}));assert.equal(stopped.cleanup.approved,false);assert.equal((await ok(await request(path,{account:admin}))).configuration.automaticRetention,false);return ids;
}
